// Genera todas las combinaciones rubro×zona a partir de la config.
const config = $input.first().json;
const items = [];

for (const rubro of config.rubros || []) {
  for (const zona of config.zonas || []) {
    items.push({
      json: {
        rubro: rubro.nombre,
        zona: zona.nombre,
        pitch_default: rubro.pitch_default || null,
        config_completa: config
      }
    });
  }
}

return items;

// Expande la respuesta: un item por cada lead nuevo encontrado.
const resp = $input.first().json;
const rubro = $('Generar Combinaciones').item.json.rubro;
const zona = $('Generar Combinaciones').item.json.zona;
const pitch_default = $('Generar Combinaciones').item.json.pitch_default;

const nuevos = resp.nuevos || [];

if (nuevos.length === 0) {
  return [{ json: { _skip: true, rubro, zona, mensaje: resp.message || 'Sin resultados' } }];
}

return nuevos.map(lead => ({
  json: {
    ...lead,
    rubro,
    zona,
    pitch_default
  }
}));

// Construye el mensaje de Telegram con pitch sugerido + link a WhatsApp
const lead = $input.first().json;

if (lead._skip) {
  // Si no había leads en esta búsqueda, mandamos mensaje informativo
  return [{
    json: {
      mensaje: `ℹ️ <b>${lead.rubro}</b> en <b>${lead.zona}</b>: 0 leads nuevos esta vez.`,
      skip_crm_link: true
    }
  }];
}

// Pitches por rubro (los mismos que usa el script Python)
const PITCHES = {
  "Hotel": "Hola {nombre}! Vi que están en {zona}. Soy Gonzalo de Paulero Studio. Te propongo una web con reservas online, sincronización con Booking/Airbnb y galería profesional de habitaciones. ¿Tenés 5 minutos esta semana?",
  "Restaurante": "Hola {nombre}! Vi su restaurante en {zona}. Soy Gonzalo de Paulero Studio. Te propongo una web con menú digital QR, reservas online y fotos profesionales que venden más platos. ¿Les interesaría ver una demo?",
  "Inmobiliaria": "Hola {nombre}! Soy Gonzalo de Paulero Studio. Vi su inmobiliaria en {zona} y les propongo una web con buscador de propiedades, filtros por precio/zona/tipo y captura automática de leads calificados. ¿10 minutos esta semana?",
  "Concesionaria": "Hola {nombre}! Soy Gonzalo de Paulero Studio. Vi su concesionaria en {zona} y les propongo una web profesional con catálogo de vehículos, simulador de financiación online y captura de leads. ¿Les interesaría ver un demo?",
  "Veterinaria": "Hola {nombre}! Soy Gonzalo de Paulero Studio. Vi su veterinaria en {zona} y les propongo una web con turnos online, historias clínicas digitales y tienda de alimentos. ¿Les interesaría charlar?",
  "Gimnasio": "Hola {nombre}! Soy Gonzalo de Paulero Studio. Vi su gimnasio en {zona} y les propongo una web con inscripción online, planilla de rutinas por alumno y pagos mensuales automáticos. ¿10 minutos esta semana?",
  "Panadería": "Hola {nombre}! Soy Gonzalo de Paulero Studio. Vi su panadería en {zona} y les propongo una web con catálogo de productos, pedidos online para retiro en tienda y WhatsApp integrado. ¿Charlamos?",
  "Peluquería": "Hola {nombre}! Soy Gonzalo de Paulero Studio. Vi su peluquería en {zona} y les propongo una web con reserva de turnos online, galería de trabajos y captura de clientes nuevos por Instagram. ¿Les interesaría?",
  "default": "Hola {nombre}! Soy Gonzalo de Paulero Studio, desarrollo webs profesionales para comercios en {zona}. ¿Les interesaría ver una propuesta para tener presencia online profesional? 10 minutos esta semana, sin compromiso."
};

function getPitch(rubro, nombre, zona) {
  const plantilla = PITCHES[rubro] || PITCHES["default"];
  return plantilla.replace(/\{nombre\}/g, nombre).replace(/\{zona\}/g, zona);
}

// Construir WhatsApp link
let waLink = '';
if (lead.whatsapp) {
  const pitch = getPitch(lead.rubro, lead.nombre, lead.zona);
  waLink = `https://wa.me/${lead.whatsapp}?text=${encodeURIComponent(pitch)}`;
} else if (lead.telefono) {
  const digits = (lead.telefono || '').replace(/\D/g, '');
  let normalized = digits;
  if (digits.length === 10 && digits.startsWith('0')) {
    normalized = '549' + digits.substring(1);
  } else if (digits.length === 10) {
    normalized = '549' + digits;
  } else if (digits.length === 7 || digits.length === 8) {
    normalized = '54935' + digits;
  }
  if (normalized.length >= 7) {
    const pitch = getPitch(lead.rubro, lead.nombre, lead.zona);
    waLink = `https://wa.me/${normalized}?text=${encodeURIComponent(pitch)}`;
  }
}

const pitch = getPitch(lead.rubro, lead.nombre, lead.zona);
const pitchCorto = pitch.length <= 280 ? pitch : pitch.substring(0, 277) + '…';

const emoji = lead.prioridad === 'Alta' ? '🔥' : lead.prioridad === 'Media' ? '🟡' : '⚪';

let msg = `${emoji} <b>${lead.nombre}</b>\n`;
msg += `📍 ${lead.rubro} en ${lead.zona}\n`;
if (lead.direccion) msg += `🏠 ${lead.direccion}\n`;
if (lead.telefono) msg += `📞 ${lead.telefono}\n`;
if (lead.webUrl) {
  const urlCorta = lead.webUrl.length > 60 ? lead.webUrl.substring(0, 57) + '…' : lead.webUrl;
  msg += `🌐 <a href="${lead.webUrl}">${urlCorta}</a>\n`;
}
if (lead.estadoWeb) msg += `📊 Web: ${lead.estadoWeb}\n`;
if (lead.redesSociales) msg += `📱 ${lead.redesSociales}\n`;
msg += `\n💬 <i>Pitch sugerido:</i>\n${pitchCorto}\n`;
msg += `\n`;
if (waLink) {
  msg += `🟢 <a href="${waLink}">Abrir WhatsApp con pitch listo</a>`;
} else {
  msg += `⚠️ Sin teléfono — buscalo en Google/IG`;
}

return [{
  json: {
    mensaje: msg,
    lead_id: lead.id,
    prioridad: lead.prioridad,
    rubro: lead.rubro,
    zona: lead.zona
  }
}];
